-- mh3sp database schema (SQLite).
--
-- Before 1.0.0 this is the only migration and it is rewritten in place: any change means resetting the database
-- (`scripts/dev.sh --reset`). From 1.0.0 on, migrations only go forward. The reasoning behind each table is in
-- ../docs/schema.md.
--
-- Conventions:
-- - STRICT tables: SQLite enforces the declared column types.
-- - Internal `INTEGER PRIMARY KEY` ids never leave the database; what people reference has a `public_id`
--   (UUID v7, 16 bytes, generated by the server: SQLite has no UUID functions).
-- - Enumerations are TEXT with a CHECK. Format checks use GLOB (SQLite has no regular expressions by default).
-- - Texts are a dictionary in the code, settings live in mh3sp.toml (both come to the database with the website,
--   M8). Terms are overrides of the terms built into the code.
-- - Timestamps are UTC, 'YYYY-MM-DD HH:MM:SS' text (CURRENT_TIMESTAMP).
-- - Foreign keys are enforced because the server enables them on every connection (off by default in SQLite).

-- Overrides of the terms and sub-terms; each edit is a new row whose id is the version sent to the console.
-- The console remembers the version it accepted and shows the terms again when the server's differs; ids only
-- grow, so an edit is always shown again.
-- Current: latest row for (kind, console language) -> latest for (kind, 'en') -> built-in.
CREATE TABLE terms (
    -- AUTOINCREMENT: without it SQLite may reuse the highest id after a deletion, and a version would go down.
    -- From 2: the terms built into the code are version 1 (sequence seeded below), so the first override is newer.
    -- At most 4294967295 (2^32 - 1): the version travels as a 32-bit unsigned field (AnsTermsVersion).
    id          INTEGER PRIMARY KEY AUTOINCREMENT CHECK (id BETWEEN 2 AND 4294967295),
    kind        TEXT NOT NULL CHECK (kind IN ('terms', 'subterms')),
    -- ISO 639-1: the game's languages are fixed (en, fr, de, it, es; ja later) and have no regional variants.
    language    TEXT NOT NULL CHECK (language GLOB '[a-z][a-z]'),
    value       TEXT NOT NULL,
    created_at  TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
) STRICT;
CREATE INDEX terms_current ON terms (kind, language, id DESC);

-- World servers, server types (with their HR limits) and the world layout are not in the database: they are game
-- constants in the code.

-- A Wii, as our Nintendo login sees it (architecture decision 13): its MAC and serial, the pair a real Wii can't
-- change, stored only as HMAC-SHA256(pepper, macadr ‖ csnum). For bans that survive a deleted save.
CREATE TABLE devices (
    id                  INTEGER PRIMARY KEY,
    public_id           BLOB NOT NULL UNIQUE CHECK (length(public_id) = 16),
    mac_serial_hmac     BLOB NOT NULL UNIQUE CHECK (length(mac_serial_hmac) = 32),
    created_at          TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_seen_at        TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
) STRICT;

-- A console, identified by HMAC-SHA256(pepper, online support code); the code itself is never stored.
CREATE TABLE consoles (
    id                  INTEGER PRIMARY KEY,
    public_id           BLOB NOT NULL UNIQUE CHECK (length(public_id) = 16),
    support_code_hmac   BLOB NOT NULL UNIQUE CHECK (length(support_code_hmac) = 32),
    region              TEXT NOT NULL CHECK (region IN ('RMHP08', 'RMHE08', 'RMHJ08')),
    -- The last Wii it logged in from.
    device_id           INTEGER REFERENCES devices (id),
    created_at          TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_seen_at        TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
) STRICT;

-- One of a console's 6 Capcom ID slots (an online identity a hunter of the save plays under).
-- Another hunter taking the slot overwrites name and profile and drops its social links; the Capcom ID and its
-- moderation records stay.
CREATE TABLE hunters (
    id              INTEGER PRIMARY KEY,
    public_id       BLOB NOT NULL UNIQUE CHECK (length(public_id) = 16),
    console_id      INTEGER NOT NULL REFERENCES consoles (id) ON DELETE CASCADE,
    slot            INTEGER NOT NULL CHECK (slot BETWEEN 1 AND 6),
    capcom_id       TEXT NOT NULL UNIQUE CHECK (length(capcom_id) = 6 AND capcom_id NOT GLOB '*[^0-9A-Z]*'),
    name            BLOB NOT NULL,     -- as the game sends it (may be Shift-JIS)
    created_at      TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_seen_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (console_id, slot)
) STRICT;
CREATE INDEX hunters_console ON hunters (console_id);

-- A hunter's public profile, from the 256-byte block the console writes and other consoles draw the hunter from
-- (game/profile.rs maps every byte and validates it as the game does). Self-reported: the save is the truth. Kept
-- for the website (hunter pages) and anti-cheat (M9). Where the player is (city settings, server type, in a party)
-- isn't kept. `unknown_*` and `appearance_*` are save bytes whose meaning isn't known yet, named by their offset.
-- Only the certain ranges are checked here (each field's width in the block, gender, lengths): the game's own
-- rules, as we inferred them, are checked by profile.rs, where widening one is a line rather than a table rebuild.
CREATE TABLE hunter_profiles (
    hunter_id       INTEGER PRIMARY KEY REFERENCES hunters (id) ON DELETE CASCADE,
    hr              INTEGER NOT NULL CHECK (hr BETWEEN 0 AND 65535),
    weapon_type     INTEGER NOT NULL CHECK (weapon_type BETWEEN 0 AND 255),
    gender          INTEGER NOT NULL CHECK (gender IN (0, 1)),
    voice           INTEGER NOT NULL CHECK (voice BETWEEN 0 AND 255),
    hair_colour     INTEGER NOT NULL,  -- RGBA
    inner_colour    INTEGER NOT NULL,  -- RGBA
    appearance_02   INTEGER NOT NULL CHECK (appearance_02 BETWEEN 0 AND 255),
    appearance_03   INTEGER NOT NULL CHECK (appearance_03 BETWEEN 0 AND 255),
    appearance_96   INTEGER NOT NULL CHECK (appearance_96 BETWEEN 0 AND 255),
    appearance_98   INTEGER NOT NULL CHECK (appearance_98 BETWEEN 0 AND 255),
    appearance_99   INTEGER NOT NULL CHECK (appearance_99 BETWEEN 0 AND 255),
    poogie_costume  INTEGER NOT NULL CHECK (poogie_costume BETWEEN 0 AND 255),
    title           INTEGER NOT NULL CHECK (title BETWEEN 0 AND 255),
    status          INTEGER NOT NULL CHECK (status BETWEEN 0 AND 255),
    comment         BLOB NOT NULL CHECK (length(comment) <= 85),  -- as the game sends it (may be Shift-JIS)
    unknown_04      INTEGER NOT NULL CHECK (unknown_04 BETWEEN 0 AND 255),
    unknown_7c      BLOB NOT NULL CHECK (length(unknown_7c) = 5),
    unknown_81      BLOB NOT NULL CHECK (length(unknown_81) = 17),
    unknown_92      INTEGER NOT NULL CHECK (unknown_92 BETWEEN 0 AND 255),
    unknown_93      INTEGER NOT NULL CHECK (unknown_93 BETWEEN 0 AND 255),
    unknown_9a      INTEGER NOT NULL CHECK (unknown_9a BETWEEN 0 AND 255),
    unknown_9b      INTEGER NOT NULL CHECK (unknown_9b BETWEEN 0 AND 255),
    updated_at      TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
) STRICT;

-- A hunter's equipment, by slot: 0 weapon, 1 bowgun barrel, 2 bowgun stock, 3 helmet, 4 chest, 5 waist, 6 arms,
-- 7 legs, 8 talisman. Kinds are the game's equipment classes; item 0 is nothing worn. Which kind and item go in
-- which slot is the game's rule, checked by profile.rs.
CREATE TABLE hunter_equipment (
    hunter_id   INTEGER NOT NULL REFERENCES hunter_profiles (hunter_id) ON DELETE CASCADE,
    slot        INTEGER NOT NULL CHECK (slot BETWEEN 0 AND 8),
    kind        INTEGER NOT NULL CHECK (kind BETWEEN 0 AND 255),
    item        INTEGER NOT NULL CHECK (item BETWEEN 0 AND 65535),
    deco_count  INTEGER NOT NULL CHECK (deco_count BETWEEN 0 AND 255),
    deco_level  INTEGER NOT NULL CHECK (deco_level BETWEEN 0 AND 65535),
    skill_1     INTEGER NOT NULL CHECK (skill_1 BETWEEN 0 AND 65535),
    skill_2     INTEGER NOT NULL CHECK (skill_2 BETWEEN 0 AND 65535),
    skill_3     INTEGER NOT NULL CHECK (skill_3 BETWEEN 0 AND 65535),
    PRIMARY KEY (hunter_id, slot)
) STRICT;

-- Friendships are mutual: one row per pair, the lower hunter id first, so a pair has one order; either side
-- deleting it ends it for both.
CREATE TABLE friends (
    hunter_a    INTEGER NOT NULL REFERENCES hunters (id) ON DELETE CASCADE,
    hunter_b    INTEGER NOT NULL REFERENCES hunters (id) ON DELETE CASCADE,
    created_at  TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (hunter_a, hunter_b),
    CHECK (hunter_a < hunter_b)
) STRICT;
CREATE INDEX friends_b ON friends (hunter_b);

-- Messages to a hunter's inbox, with or without a friend request (`ReqTell`, `ReqFriendAdd`). The game's inbox
-- only lasts until it quits and drops what arrives while a scene loads, and deleting from it is local: so the server
-- stores them and delivers each once, at the recipient's next position in a city. A plain message goes once
-- delivered; a friend request stays as the proof an answer needs. Both expire 30 days after their (last) sending;
-- sending a request again delivers it again. A blocked sender's messages are never stored.
CREATE TABLE messages (
    id              INTEGER PRIMARY KEY,
    -- NULL: from the server or the website (system messages, a could do); never a friend request.
    from_hunter     INTEGER REFERENCES hunters (id) ON DELETE CASCADE,
    to_hunter       INTEGER NOT NULL REFERENCES hunters (id) ON DELETE CASCADE,
    text            BLOB NOT NULL,     -- as the game sends it (may be Shift-JIS)
    friend_request  INTEGER NOT NULL CHECK (friend_request IN (0, 1)),
    sent            INTEGER NOT NULL DEFAULT 0 CHECK (sent IN (0, 1)),
    created_at      TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (from_hunter <> to_hunter),
    CHECK (friend_request = 0 OR from_hunter IS NOT NULL)
) STRICT;
CREATE INDEX messages_to ON messages (to_hunter, sent);
-- One request per pair: a new one replaces it.
CREATE UNIQUE INDEX messages_one_request ON messages (from_hunter, to_hunter) WHERE friend_request = 1;

-- Black lists are personal: (a, b) and (b, a) are separate rows, only the blocker removes theirs. The server
-- doesn't deliver to a blocker what their blocked hunters send them.
CREATE TABLE blacklist (
    blocker     INTEGER NOT NULL REFERENCES hunters (id) ON DELETE CASCADE,
    blocked     INTEGER NOT NULL REFERENCES hunters (id) ON DELETE CASCADE,
    created_at  TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (blocker, blocked),
    CHECK (blocker <> blocked)
) STRICT;
CREATE INDEX blacklist_blocked ON blacklist (blocked);

-- Who signs in to the API (the admin CLI, later the website): players and staff alike, the role says which.
CREATE TABLE roles (
    id      INTEGER PRIMARY KEY,
    name    TEXT NOT NULL UNIQUE
) STRICT;

CREATE TABLE users (
    id              INTEGER PRIMARY KEY,
    public_id       BLOB NOT NULL UNIQUE CHECK (length(public_id) = 16),
    -- Lower case: one person, one row.
    email           TEXT NOT NULL UNIQUE CHECK (email GLOB '?*@?*' AND email = lower(email)),
    -- argon2 (PHC string); none until the website's sign-in: such a user has tokens only.
    password_hash   TEXT,
    role_id         INTEGER NOT NULL REFERENCES roles (id),
    created_at      TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
) STRICT;

-- What a token is for, and how long it lives.
CREATE TABLE usages (
    id                  INTEGER PRIMARY KEY,
    name                TEXT NOT NULL UNIQUE,
    -- NULL: until revoked.
    lifetime_seconds    INTEGER CHECK (lifetime_seconds > 0)
) STRICT;

-- API tokens, `<key>.<secret>`: the key (`mh3sp_<public>`, shown in lists) and the SHA-256 of the whole token are
-- stored, never the secret. Expiry: created_at + the usage's lifetime. Revoked, never deleted.
CREATE TABLE tokens (
    id                  INTEGER PRIMARY KEY,
    key                 TEXT NOT NULL UNIQUE CHECK (key GLOB 'mh3sp_?*'),
    hash                BLOB NOT NULL UNIQUE CHECK (length(hash) = 32),
    user_id             INTEGER NOT NULL REFERENCES users (id),
    usage_id            INTEGER NOT NULL REFERENCES usages (id),
    created_at          TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    revoked_at          TEXT,
    revocation_reason   TEXT,
    CHECK ((revoked_at IS NULL) = (revocation_reason IS NULL))
) STRICT;
CREATE INDEX tokens_user ON tokens (user_id);

-- Bans (and later the whitelist): one rule on one target, a console, a hunter, a Wii or a user. A ban on a console stops
-- all its hunters (a banned player can't switch slots), and comes with a ban on its Wii (a new save doesn't lift it).
-- Revoked, never deleted.
CREATE TABLE rule_kinds (
    id      INTEGER PRIMARY KEY,
    name    TEXT NOT NULL UNIQUE
) STRICT;

CREATE TABLE access_rules (
    id                  INTEGER PRIMARY KEY,
    public_id           BLOB NOT NULL UNIQUE CHECK (length(public_id) = 16),
    kind_id             INTEGER NOT NULL REFERENCES rule_kinds (id),
    console_id          INTEGER REFERENCES consoles (id),
    hunter_id           INTEGER REFERENCES hunters (id),
    device_id           INTEGER REFERENCES devices (id),
    user_id             INTEGER REFERENCES users (id),
    reason              TEXT NOT NULL,
    -- NULL: the operator (the binary, or an admin of the configuration's `admins`, who isn't a user yet).
    created_by          INTEGER REFERENCES users (id),
    created_at          TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- NULL: until revoked.
    expires_at          TEXT,
    revoked_at          TEXT,
    revocation_reason   TEXT,
    CHECK ((console_id IS NOT NULL) + (hunter_id IS NOT NULL) + (device_id IS NOT NULL) + (user_id IS NOT NULL) = 1),
    CHECK ((revoked_at IS NULL) = (revocation_reason IS NULL))
) STRICT;
CREATE INDEX access_rules_console ON access_rules (console_id) WHERE console_id IS NOT NULL;
CREATE INDEX access_rules_device ON access_rules (device_id) WHERE device_id IS NOT NULL;

-- Initial data.

-- Terms overrides start at 2: AUTOINCREMENT continues after the sequence's value.
INSERT INTO sqlite_sequence (name, seq) VALUES ('terms', 1);

INSERT INTO roles (name) VALUES ('player'), ('admin');
INSERT INTO rule_kinds (name) VALUES ('ban'), ('allow');
-- The CLI's tokens live until revoked; the website's sessions a month.
INSERT INTO usages (name, lifetime_seconds) VALUES ('cli', NULL), ('session', 2592000);
